<?php
require_once __DIR__ . '/includes.php';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
 csrf_check();$action=(string)($_POST['action']??'save');
 if($action==='delete') {db()->prepare('DELETE FROM products WHERE id=?')->execute([(int)($_POST['id']??0)]);flash('success','Produk dihapus.');redirect('products.php');}
 $id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$sku=trim((string)($_POST['sku']??''));$description=trim((string)($_POST['description']??''));$short=trim((string)($_POST['short_description']??''));$image=trim((string)($_POST['image']??''));$category=(int)($_POST['category_id']??0);$price=max(0,(float)($_POST['price']??0));$sale=trim((string)($_POST['sale_price']??''));$stock=max(0,(int)($_POST['stock']??0));$featured=isset($_POST['featured'])?1:0;$active=isset($_POST['active'])?1:0;
 if($name===''||$sku===''||strlen($name)>180||strlen($sku)>80||($sale!==''&&(float)$sale >= $price)){flash('error','Nama dan SKU wajib diisi; harga diskon harus lebih rendah dari harga normal.');redirect('products.php'.($id?'?edit='.$id:''));}
 $slug=slugify($name);$base=$slug;$n=2;while(true){$check=db()->prepare('SELECT id FROM products WHERE slug=? AND id<>?');$check->execute([$slug,$id]);if(!$check->fetch())break;$slug=$base.'-'.$n++;}
 try {if($id){db()->prepare('UPDATE products SET name=?,slug=?,sku=?,short_description=?,description=?,category_id=?,price=?,sale_price=?,image=?,stock=?,featured=?,active=? WHERE id=?')->execute([$name,$slug,$sku,$short,$description,$category?:null,$price,$sale!==''?(float)$sale:null,$image,$stock,$featured,$active,$id]);}else{db()->prepare('INSERT INTO products(name,slug,sku,short_description,description,category_id,price,sale_price,image,stock,featured,active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$name,$slug,$sku,$short,$description,$category?:null,$price,$sale!==''?(float)$sale:null,$image,$stock,$featured,$active]);}flash('success','Produk tersimpan.');}catch(Throwable $exception){error_log('[KELOMPOK6] Product save failed: '.$exception->getMessage());flash('error','Produk gagal disimpan. Periksa SKU dan URL gambar.');}redirect('products.php');
}
$categories=db()->query('SELECT id,name FROM categories ORDER BY sort_order,name')->fetchAll();$edit=null;if(isset($_GET['edit'])){$stmt=db()->prepare('SELECT * FROM products WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch();}$products=db()->query('SELECT p.*,c.name AS category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC LIMIT 300')->fetchAll();
admin_header('Products');
?><section class="admin-panel"><h2><?=$edit?'Edit product':'Add product'?></h2><form method="post" class="admin-product-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><label>Product name<input name="name" maxlength="180" required value="<?=e($edit['name']??'')?>"></label><label>SKU<input name="sku" maxlength="80" required value="<?=e($edit['sku']??'')?>"></label><label>Category<select name="category_id"><option value="0">Uncategorized</option><?php foreach($categories as $c): ?><option value="<?=(int)$c['id']?>" <?=($edit['category_id']??0)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach; ?></select></label><label>Image path/URL<input name="image" maxlength="255" value="<?=e($edit['image']??'')?>" placeholder="assets/images/product.jpg"></label><label>Price<input type="number" min="0" step="0.01" name="price" required value="<?=e($edit['price']??'0')?>"></label><label>Sale price (optional)<input type="number" min="0" step="0.01" name="sale_price" value="<?=e($edit['sale_price']??'')?>"></label><label>Stock<input type="number" min="0" name="stock" value="<?=e($edit['stock']??'0')?>"></label><label>Short description<input name="short_description" maxlength="500" value="<?=e($edit['short_description']??'')?>"></label><label class="admin-wide">Description<textarea name="description" rows="5"><?=e($edit['description']??'')?></textarea></label><label><input type="checkbox" name="featured" value="1" <?=!empty($edit['featured'])?'checked':''?>> Featured</label><label><input type="checkbox" name="active" value="1" <?=!isset($edit['active'])||$edit['active']?'checked':''?>> Active</label><button class="button button-dark" type="submit">SAVE PRODUCT</button><?php if($edit): ?><a href="products.php">Cancel edit</a><?php endif; ?></form></section><section class="admin-panel"><h2>Product inventory</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>State</th><th>Actions</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?=e($p['name'])?><br><small><?=e($p['sku'])?></small></td><td><?=e($p['category_name']??'—')?></td><td><?=e(money($p['price']))?></td><td><?=(int)$p['stock']?></td><td><?=$p['active']?'Active':'Hidden'?></td><td><a href="products.php?edit=<?=(int)$p['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this product?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="text-button" type="submit">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section><?php admin_footer(); ?>
